BEGIN
IF current_user<>'postgres' THEN RAISE EXCEPTION 'C1266_PREREQ9_OWNER_REQUIRED'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0));
